// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    ReentrancyDAO c;
    function setUp() public { c = new ReentrancyDAO(); }

    // Fuzzed params: deposit amount and a boolean controlling whether the helper reverts on receive.
    function testFuzz_property(uint256 depositAmount, bool shouldRevert) public {
        vm.assume(depositAmount <= VALUE_CAP);
        // keep depositAmount in a reasonable range and non-zero so the behavior matters
        depositAmount = bound(depositAmount, 1, 1 ether);

        // deploy a helper that can be toggled to revert or accept
        RevertingReceiver helper = new RevertingReceiver();
        helper.setShouldRevert(shouldRevert);

        // fund the helper so it can be msg.sender for deposit if needed
        address depositor = address(this);
        vm.deal(depositor, 2 ether);

        // make deposit from depositor into c under the depositor identity
        vm.prank(depositor);
        c.deposit{value: depositAmount}();

        // now simulate that the depositor is the helper (we need the callee to be the one receiving withdrawAll send)
        // so first set credit mapping entry for helper by making helper deposit
        // fund helper
        vm.deal(address(helper), 2 ether);
        // have helper deposit its own credit
        helper.depositTo(address(c), depositAmount);

        // Now call withdrawAll as the helper (so c will call helper.receive/fallback)
        bool ok;
        vm.prank(address(helper));
        try c.withdrawAll() {
            ok = true;
        } catch {
            ok = false;
        }

        // GENERAL RULE (single assert): For the reference C, when the callee reverts on receive, the call to withdrawAll must revert (ok == false).
        // The mutant that removed the external call will not revert in that scenario, so this assertion distinguishes them.
        if (shouldRevert) {
            assertTrue(!ok);
        } else {
            // when the callee accepts, withdrawAll should succeed
            assertTrue(ok);
        }
    }
}

// Helper that can be instructed to revert or accept on receive; it also can deposit into C to set up credit.
contract RevertingReceiver {
    bool public shouldRevert;
    ReentrancyDAO public c;

    function setShouldRevert(bool v) public {
        shouldRevert = v;
    }

    // deposit into target contract so this helper becomes a credited caller
    function depositTo(address target, uint256 amt) public payable {
        c = ReentrancyDAO(target);
        // forward deposit from this contract; ensure contract has funds
        // caller must fund this contract externally in the test
        c.deposit{value: amt}();
    }

    receive() external payable {
        if (shouldRevert) revert("reverting receiver");
    }
}
